// Stripe signature check, step 1: read the signing secret, parse the Stripe-Signature header, build the signed payload.
const CFG = { signingSecret: "whsec_REPLACE_ME" };   // paste your Stripe webhook signing secret here, or set the environment variable STRIPE_WEBHOOK_SECRET
let secret = CFG.signingSecret;
try { if (typeof $env !== "undefined" && $env && $env.STRIPE_WEBHOOK_SECRET) secret = $env.STRIPE_WEBHOOK_SECRET; } catch (e) {}
const item = $input.first();
const headers = item.json.headers || {};
const header = headers["stripe-signature"] || headers["Stripe-Signature"] || "";
let raw = "";
try { raw = (item.binary && item.binary.data) ? Buffer.from(item.binary.data.data, "base64").toString("utf8") : ""; } catch (e) { raw = ""; }
// While a signing secret is being rotated Stripe sends two v1 values, so keep all of them.
const v1 = []; let ts = 0;
header.split(",").forEach((p) => { const i = p.indexOf("="); if (i < 1) return; const k = p.slice(0, i).trim(), v = p.slice(i + 1).trim(); if (k === "t") ts = parseInt(v, 10) || 0; if (k === "v1") v1.push(v); });
return [{ json: { ...item.json, _sig: { signedPayload: ts + "." + raw, v1, ts, hasHeader: !!header, hasBody: !!raw, secret, secretSet: secret.startsWith("whsec_") && secret !== "whsec_REPLACE_ME" } } }];

// Stripe signature check, step 3: compare in constant time, enforce the 5-minute window, stop the run if anything is wrong.
// A bad request stops here with a clear message, so it shows up in your executions instead of vanishing.
const s = $input.first().json;
const sig = s._sig || {};
if (!sig.secretSet) throw new Error("Stripe signing secret not set. Paste your whsec_ secret in 'Prepare signature check' or set the STRIPE_WEBHOOK_SECRET environment variable.");
if (!sig.hasHeader || !sig.hasBody) throw new Error("No Stripe-Signature header or no raw body. Check that Raw Body is on in the Webhook node and that the request really comes from Stripe.");
const computed = String(s.computedSig || "").toLowerCase();
const ok = (sig.v1 || []).some((v) => {
  v = String(v).toLowerCase();
  if (!computed || v.length !== computed.length) return false;
  let diff = 0;
  for (let i = 0; i < v.length; i++) diff |= v.charCodeAt(i) ^ computed.charCodeAt(i);
  return diff === 0;
});
if (!ok) throw new Error("Stripe signature did not match. Wrong signing secret (test and live endpoints have different ones) or the request is not from Stripe.");
if (Math.abs(Math.floor(Date.now() / 1000) - sig.ts) > 300) throw new Error("Stripe signature is more than 5 minutes old, rejected as a possible replay.");
return [{ json: { headers: s.headers, params: s.params, query: s.query, body: s.body } }];

// Stripe re-sends webhooks. Drop any event id we have already seen (keeps the last 500).
const e = $input.first().json.body ?? $input.first().json;
const s = $getWorkflowStaticData("global");
s.seen = s.seen || [];
if (e.id && s.seen.includes(e.id)) { return []; }
if (e.id) { s.seen.push(e.id); if (s.seen.length > 500) s.seen = s.seen.slice(-500); }
return $input.all();

// Read the REAL decline code from the payment intent and pick a recovery plan.
// Stripe API 2025-03-31 (basil) and later: the invoice has no payment_intent, so the fetch returns an invoice_payments list
// with the payment intent expanded. Older versions return the payment intent itself. Normalize both.
const fetched = $input.first().json || {};
let pi = fetched;
if (pi.object === "list") {
  const p0 = Array.isArray(pi.data) ? pi.data[0] : null;
  const x = p0 && p0.payment && p0.payment.payment_intent;
  pi = (x && typeof x === "object") ? x : {};
}
// The Stripe lookup is set to continue on error, so a failed call arrives here as an item with an error. That is a problem on your side
// (expired key, rate limit, missing permission), not the customer's, so it gets its own route instead of being treated as a decline.
const lookupFailed = !!fetched.error || pi.object !== "payment_intent";
const cfg = $("Set decline code groups").first().json;
const w = $("Receive Stripe failed payment event").first().json;
const evt = w.body ? w.body : w;
const o = (evt.data && evt.data.object) ? evt.data.object : {};
const list = (v) => String(v || "").split(",").map(x => x.trim()).filter(Boolean);
const lpe = pi.last_payment_error || null;
// A payment waiting on the cardholder (3D Secure) has no error object, only status requires_action.
const code = lpe ? (lpe.decline_code || lpe.code) : (pi.status === "requires_action" ? "authentication_required" : "unknown");
const adviceCode = lpe ? (lpe.advice_code || null) : null;
let route = "soft_retry", action = "Retry in 1, 3 and 7 days, then email the customer.";
if (list(cfg.hardDeclineCodes).includes(code) || adviceCode === "do_not_try_again") { route = "hard_no_retry"; action = "Do not retry. Email the customer a card-update link now."; }
else if (list(cfg.authenticationCodes).includes(code) || pi.status === "requires_action") { route = "auth_required"; action = "Do not retry, it cannot succeed. Send the customer the invoice's hosted payment link so they can confirm the payment with their bank."; }
else if (list(cfg.insufficientFundsCodes).includes(code)) { route = "payday_retry"; action = "Retry after 24 hours, then on the 1st or 15th (payday)."; }
else if (list(cfg.technicalErrorCodes).includes(code)) { route = "technical_retry"; action = "Retry in 1, 6 and 24 hours. These usually clear on their own."; }
if (lookupFailed) { route = "lookup_failed"; action = "The Stripe lookup failed (expired API key, rate limit or missing permission). Alert yourself and do NOT email the customer."; }
// next_payment_attempt empty on the event = Stripe itself will NOT retry this invoice again.
const stripeWillRetry = ("next_payment_attempt" in o) ? !!o.next_payment_attempt : null;
return [{ json: { invoice: o.id, customer: o.customer, email: o.customer_email || "", amount: (o.amount_due || 0) / 100, currency: o.currency || "usd",
  declineCode: lookupFailed ? "lookup_failed" : code, route, action, stripeWillRetry, attempt: o.attempt_count || 1,
  hostedInvoiceUrl: (typeof o.hosted_invoice_url === "string" && o.hosted_invoice_url.indexOf("https://") === 0) ? o.hosted_invoice_url : "" } }];
